import './styles.css';
import { initBgmToggle, setBgmToggleLanguage } from './bgm.js';

const defaultLanguage = 'en';
const supportedLanguages = ['zh', 'en'];
const hubSearchParams = new URLSearchParams(window.location.search);
const initialLanguage = hubSearchParams.get('lang') || defaultLanguage;
const debugMode = hubSearchParams.get('debug') === '1';
const EXPERIENCE_SWITCHER_STORAGE_KEY = 'gamex:experience-switcher-collapsed';

let language = supportedLanguages.includes(initialLanguage) ? initialLanguage : defaultLanguage;
document.documentElement.lang = language;

const copy = {
  zh: {
    switcherLabel: 'GameX 体验切换',
    languageLabel: '语言',
    collapseSwitcher: '收起体验切换器',
    expandSwitcher: '展开体验切换器',
    experiences: {
      'game-boy': { label: 'GX Pocket', visibleLabel: 'GAME BOY', shortLabel: 'GB' },
      dammagotchi: { label: '电子宠物', visibleLabel: '电子宠物', shortLabel: 'TAMA' },
    },
  },
  en: {
    switcherLabel: 'GameX experience switcher',
    languageLabel: 'Language',
    collapseSwitcher: 'Hide experience switcher',
    expandSwitcher: 'Show experience switcher',
    experiences: {
      'game-boy': { label: 'GX Pocket', visibleLabel: 'GAME BOY', shortLabel: 'GB' },
      dammagotchi: { label: 'Tamagotchi', visibleLabel: 'TAMAGOTCHI', shortLabel: 'TAMA' },
    },
  },
};

const experiences = [
  {
    id: 'game-boy',
    source: 'game-boy/index.html',
    accent: '#3c3c43',
  },
  {
    id: 'dammagotchi',
    source: 'dammagotchi/index.html',
    accent: '#3c3c43',
  },
];

const initialId = hubSearchParams.get('app') || window.location.hash.replace('#', '') || 'game-boy';
let activeId = experiences.some((item) => item.id === initialId) ? initialId : 'game-boy';

function readBooleanPreference(key, fallback = false) {
  try {
    const value = window.localStorage.getItem(key);
    return value === null ? fallback : value === 'true';
  } catch {
    return fallback;
  }
}

function writeBooleanPreference(key, value) {
  try {
    window.localStorage.setItem(key, String(value));
  } catch {
    // Storage can be unavailable in privacy/file contexts; in-memory state still works.
  }
}

let switcherCollapsed = readBooleanPreference(EXPERIENCE_SWITCHER_STORAGE_KEY);

const app = document.querySelector('#app');

function experienceUrl(experience) {
  const params = new URLSearchParams({ lang: language });
  if (debugMode) {
    params.set('debug', '1');
  }
  return `${experience.source}?${params.toString()}`;
}

function getKeyboardOrderedExperiences(activeExperienceId) {
  const activeExperience = experiences.find((item) => item.id === activeExperienceId);
  if (!activeExperience) {
    return [...experiences];
  }
  return [activeExperience, ...experiences.filter((item) => item.id !== activeExperienceId)];
}

function setSwitcherCollapsed(
  collapsed,
  { persist = true, restoreFocus = true } = {},
) {
  switcherCollapsed = collapsed;

  if (persist) {
    writeBooleanPreference(EXPERIENCE_SWITCHER_STORAGE_KEY, collapsed);
  }

  const switcher = app.querySelector('.experience-switcher');
  const capsule = app.querySelector('#experience-switcher-capsule');
  const collapseButton = app.querySelector('#experience-switcher-collapse');
  const expandButton = app.querySelector('#experience-switcher-expand');

  if (!switcher || !capsule || !collapseButton || !expandButton) {
    return;
  }

  switcher.classList.toggle('is-collapsed', collapsed);
  capsule.hidden = collapsed;
  capsule.setAttribute('aria-hidden', String(collapsed));
  expandButton.hidden = !collapsed;
  expandButton.setAttribute('aria-hidden', String(!collapsed));
  collapseButton.setAttribute('aria-expanded', String(!collapsed));
  expandButton.setAttribute('aria-expanded', String(!collapsed));

  if (restoreFocus) {
    (collapsed ? expandButton : collapseButton).focus();
  }
}

function render() {
  const active = experiences.find((item) => item.id === activeId);
  const activeCopy = copy[language].experiences[active.id];
  document.documentElement.style.setProperty('--accent', active.accent);

  const switcherMarkup = `
    <aside class="experience-switcher" aria-label="${copy[language].switcherLabel}">
      <div
        class="experience-switcher__capsule"
        id="experience-switcher-capsule"
        ${switcherCollapsed ? 'hidden' : ''}
        aria-hidden="${switcherCollapsed}"
      >
        <nav class="experience-switcher__segments" aria-label="${copy[language].switcherLabel}">
          ${getKeyboardOrderedExperiences(active.id).map((item) => {
            const itemCopy = copy[language].experiences[item.id];
            const isActive = item.id === active.id;
            return `
              <button
                type="button"
                class="experience-segment ${isActive ? 'is-active' : ''}"
                data-id="${item.id}"
                aria-label="${itemCopy.label}"
                aria-pressed="${isActive}"
              >
                <span class="experience-segment__full">${itemCopy.visibleLabel}</span>
                <span class="experience-segment__short" aria-hidden="true">${itemCopy.shortLabel}</span>
              </button>`;
          }).join('')}
        </nav>
        <button
          type="button"
          class="experience-switcher__collapse"
          id="experience-switcher-collapse"
          aria-label="${copy[language].collapseSwitcher}"
          aria-controls="experience-switcher-capsule"
          aria-expanded="${!switcherCollapsed}"
        ><span aria-hidden="true">−</span></button>
        ${active.id === 'dammagotchi' ? `
          <div class="experience-switcher__languages" id="language-toggle" aria-label="${copy[language].languageLabel}">
            <button type="button" data-language="zh" class="${language === 'zh' ? 'is-active' : ''}">中文</button>
            <button type="button" data-language="en" class="${language === 'en' ? 'is-active' : ''}">English</button>
          </div>` : ''}
      </div>
      <button
        type="button"
        class="experience-switcher__handle"
        id="experience-switcher-expand"
        ${switcherCollapsed ? '' : 'hidden'}
        aria-label="${copy[language].expandSwitcher}"
        aria-controls="experience-switcher-capsule"
        aria-expanded="${!switcherCollapsed}"
        aria-hidden="${!switcherCollapsed}"
      >GX</button>
    </aside>`;

  app.innerHTML = `
    <main class="shell" data-active="${active.id}">
      <section class="stage" aria-label="${activeCopy.label}">
        <iframe
          class="experience-frame"
          title="${activeCopy.label}"
          src="${experienceUrl(active)}"
          allow="fullscreen; autoplay; gamepad; clipboard-read; clipboard-write"
          referrerpolicy="no-referrer"
        ></iframe>
      </section>
      ${switcherMarkup}
    </main>
  `;

  const switcher = app.querySelector('.experience-switcher');
  const collapseButton = app.querySelector('#experience-switcher-collapse');
  const expandButton = app.querySelector('#experience-switcher-expand');

  collapseButton?.addEventListener('click', () => {
    setSwitcherCollapsed(true);
  });

  expandButton?.addEventListener('click', () => {
    setSwitcherCollapsed(false);
  });

  switcher?.addEventListener('keydown', (event) => {
    if (
      event.key === 'Escape'
      && !switcherCollapsed
      && switcher.contains(document.activeElement)
    ) {
      event.preventDefault();
      event.stopPropagation();
      setSwitcherCollapsed(true);
    }
  });

  for (const button of app.querySelectorAll('.experience-segment')) {
    button.addEventListener('click', () => {
      const nextId = button.dataset.id;
      if (!nextId || nextId === activeId) {
        return;
      }

      activeId = nextId;
      const url = new URL(window.location.href);
      url.searchParams.set('app', activeId);
      url.searchParams.set('lang', language);
      url.hash = activeId;
      window.history.replaceState({}, '', url);
      render();
    });
  }

  for (const button of app.querySelectorAll('[data-language]')) {
    button.addEventListener('click', () => {
      setLanguage(button.dataset.language);
    });
  }

  setSwitcherCollapsed(switcherCollapsed, { persist: false, restoreFocus: false });
}

function setLanguage(next) {
  if (!supportedLanguages.includes(next) || next === language) {
    return;
  }

  language = next;
  document.documentElement.lang = language;
  setBgmToggleLanguage(language);
  const url = new URL(window.location.href);
  url.searchParams.set('lang', language);
  url.searchParams.set('app', activeId);
  url.hash = activeId;
  window.history.replaceState({}, '', url);
  render();
}

function isMessageFromActiveExperience(event) {
  const activeFrame = app.querySelector('.experience-frame');
  return Boolean(
    activeFrame
    && event.source === activeFrame.contentWindow
    && event.origin === window.location.origin
  );
}

function handleExperienceMessage(event) {
  if (!isMessageFromActiveExperience(event)) {
    return;
  }

  const data = event.data;
  if (data && data.type === 'gamex:set-language') {
    setLanguage(data.language);
  }
}

window.addEventListener('message', handleExperienceMessage);

render();
initBgmToggle(language);
